// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

/**
 * Adaptivity by indirection, never by recompilation (fragment-fusion M9): {@link VariantSelector} picks a physical
 * variant per batch from observed per-batch costs (Micro-Adaptivity/POLAR-style epsilon-greedy bandit), and
 * {@link Permutation} reorders conjunctive fragment sites by observed selectivity with plain array swaps (the PCQ
 * move). Both are deterministic given their observation streams — no wall clocks, no RNG — so runs are reproducible.
 */
public final class FragmentAdaptivity {

	private FragmentAdaptivity() {
	}

	/**
	 * Epsilon-greedy per-batch variant selection over observed mean costs. Exploration is deterministic: every
	 * {@code exploreEvery}-th decision round-robins a non-greedy arm.
	 */
	public static final class VariantSelector {
		private final long[] totalCost;
		private final long[] observations;
		private final int exploreEvery;
		private long decisions;
		private int exploreCursor;

		public VariantSelector(int variants, int exploreEvery) {
			if (variants < 1) {
				throw new IllegalArgumentException("at least one variant is required");
			}
			this.totalCost = new long[variants];
			this.observations = new long[variants];
			this.exploreEvery = Math.max(2, exploreEvery);
		}

		/** The variant to run for the next batch. */
		public int choose() {
			decisions++;
			if (decisions % exploreEvery == 0) {
				exploreCursor = (exploreCursor + 1) % totalCost.length;
				return exploreCursor;
			}
			int best = 0;
			double bestMean = mean(0);
			for (int variant = 1; variant < totalCost.length; variant++) {
				double variantMean = mean(variant);
				if (variantMean < bestMean) {
					bestMean = variantMean;
					best = variant;
				}
			}
			return best;
		}

		/** Records the observed cost (any consistent unit: nanos, escapes, branch misses) of one batch. */
		public void observe(int variant, long cost) {
			totalCost[variant] += cost;
			observations[variant]++;
		}

		private double mean(int variant) {
			// unobserved variants are optimistically free so each gets tried before greed locks in
			return observations[variant] == 0 ? -1.0 : (double) totalCost[variant] / observations[variant];
		}
	}

	/**
	 * A permutable array of conjunctive fragment sites: the host evaluates sites in permutation order, records per-site
	 * tests/rejections, and periodically reorders by observed rejection rate (most selective first) — an array swap,
	 * never a recompile. Only legal for freely reorderable conjuncts (pure predicate fragments at one placement point).
	 */
	public static final class Permutation {
		private final int[] order;
		private final long[] tests;
		private final long[] rejections;

		public Permutation(int sites) {
			this.order = new int[sites];
			for (int i = 0; i < sites; i++) {
				order[i] = i;
			}
			this.tests = new long[sites];
			this.rejections = new long[sites];
		}

		/** The site to evaluate at conjunct position {@code position}. */
		public int siteAt(int position) {
			return order[position];
		}

		public int size() {
			return order.length;
		}

		public void observe(int site, long testCount, long rejectedCount) {
			tests[site] += testCount;
			rejections[site] += rejectedCount;
		}

		/** Reorders sites by descending observed rejection rate; a stable insertion sort keeps ties untouched. */
		public void reorderBySelectivity() {
			for (int i = 1; i < order.length; i++) {
				int site = order[i];
				double rate = rejectionRate(site);
				int j = i - 1;
				while (j >= 0 && rejectionRate(order[j]) < rate) {
					order[j + 1] = order[j];
					j--;
				}
				order[j + 1] = site;
			}
		}

		private double rejectionRate(int site) {
			return tests[site] == 0 ? 0.0 : (double) rejections[site] / tests[site];
		}
	}
}
